import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-forgot-password',
  templateUrl: './forgot-password.component.html',
  styleUrls: ['./forgot-password.component.css']
})
export class ForgotPasswordComponent {
  step: 'email' | 'otp' | 'newPassword' = 'email';
  
  emailForm: FormGroup;
  otpForm: FormGroup;
  newPasswordForm: FormGroup;
  
  isLoading = false;
  errorMessage = '';
  successMessage = '';
  
  userEmail = '';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {
    this.emailForm = this.fb.group({
      email: ['', [Validators.required, Validators.email]]
    });

    this.otpForm = this.fb.group({
      otp: ['', [Validators.required, Validators.pattern(/^\d{6}$/)]]
    });

    this.newPasswordForm = this.fb.group({
      otp: ['', [Validators.required, Validators.minLength(6), Validators.maxLength(6)]],
      newPassword: ['', [Validators.required, Validators.minLength(6)]],
      confirmPassword: ['', [Validators.required]]
    }, { validators: this.passwordMatchValidator });
  }

  passwordMatchValidator(form: FormGroup) {
    const password = form.get('newPassword');
    const confirmPassword = form.get('confirmPassword');
    
    if (password && confirmPassword && password.value !== confirmPassword.value) {
      confirmPassword.setErrors({ passwordMismatch: true });
      return { passwordMismatch: true };
    }
    return null;
  }

  onSubmitEmail(): void {
    if (this.emailForm.invalid) {
      this.markFormGroupTouched(this.emailForm);
      return;
    }

    this.isLoading = true;
    this.errorMessage = '';
    this.successMessage = '';

    const email = this.emailForm.value.email;
    this.userEmail = email;

    this.authService.forgotPassword({ email }).subscribe({
      next: (response) => {
        if (response.success) {
          this.successMessage = response.message || 'Mã OTP đã được gửi đến email của bạn!';
          this.step = 'otp';
          this.isLoading = false;
        } else {
          this.errorMessage = response.message || 'Gửi email thất bại';
          this.isLoading = false;
        }
      },
      error: (error) => {
        this.errorMessage = error.error?.message || 'Gửi email thất bại. Vui lòng thử lại!';
        this.isLoading = false;
      }
    });
  }

  onSubmitOtp(): void {
    if (this.otpForm.invalid) {
      this.markFormGroupTouched(this.otpForm);
      return;
    }

    this.isLoading = true;
    this.errorMessage = '';
    this.successMessage = '';

    const otp = this.otpForm.value.otp;

    this.authService.verifyOtp({ otp }).subscribe({
      next: (response) => {
        if (response.success) {
          this.successMessage = response.message || 'Mã OTP hợp lệ!';
          this.newPasswordForm.patchValue({ otp: otp });
          this.step = 'newPassword';
          this.isLoading = false;
        } else {
          this.errorMessage = response.message || 'Mã OTP không hợp lệ';
          this.isLoading = false;
        }
      },
      error: (error) => {
        this.errorMessage = error.error?.message || 'Mã OTP không hợp lệ. Vui lòng thử lại!';
        this.isLoading = false;
      }
    });
  }

  onSubmitNewPassword(): void {
    if (this.newPasswordForm.invalid) {
      this.markFormGroupTouched(this.newPasswordForm);
      return;
    }

    this.isLoading = true;
    this.errorMessage = '';
    this.successMessage = '';

    const { otp, newPassword } = this.newPasswordForm.value;

    this.authService.setNewPassword({ otp, newPassword }).subscribe({
      next: (response) => {
        if (response.success) {
          this.successMessage = response.message || 'Đặt mật khẩu mới thành công!';
          setTimeout(() => {
            this.router.navigate(['/login']);
          }, 2000);
        } else {
          this.errorMessage = response.message || 'Đặt mật khẩu thất bại';
          this.isLoading = false;
        }
      },
      error: (error) => {
        this.errorMessage = error.error?.message || 'Đặt mật khẩu thất bại. Vui lòng thử lại!';
        this.isLoading = false;
      }
    });
  }

  resendOtp(): void {
    this.onSubmitEmail();
  }

  backToLogin(): void {
    this.router.navigate(['/login']);
  }

  onOtpInput(event: any): void {
    const value = event.target.value;
    // Chỉ cho phép số
    const numericValue = value.replace(/[^0-9]/g, '');
    // Giới hạn 6 chữ số
    const limitedValue = numericValue.slice(0, 6);
    this.otpForm.patchValue({ otp: limitedValue });
  }

  private markFormGroupTouched(formGroup: FormGroup): void {
    Object.keys(formGroup.controls).forEach(key => {
      const control = formGroup.get(key);
      control?.markAsTouched();
    });
  }

  get email() {
    return this.emailForm.get('email');
  }

  get otp() {
    return this.otpForm.get('otp');
  }

  get newPassword() {
    return this.newPasswordForm.get('newPassword');
  }

  get confirmPassword() {
    return this.newPasswordForm.get('confirmPassword');
  }
}
<div class="forgot-password-container">
  <div class="forgot-password-card">
    <div class="forgot-password-header">
      <h1 *ngIf="step === 'email'">Quên Mật Khẩu</h1>
      <h1 *ngIf="step === 'otp'">Xác Thực OTP</h1>
      <h1 *ngIf="step === 'newPassword'">Đặt Mật Khẩu Mới</h1>
      
      <p *ngIf="step === 'email'">Nhập email của bạn để nhận mã OTP</p>
      <p *ngIf="step === 'otp'">Nhập mã OTP đã được gửi đến email <strong>{{ userEmail }}</strong></p>
      <p *ngIf="step === 'newPassword'">Nhập mật khẩu mới của bạn</p>
    </div>

    <!-- Step 1: Email -->
    <form *ngIf="step === 'email'" [formGroup]="emailForm" (ngSubmit)="onSubmitEmail()">
      <div *ngIf="errorMessage" class="alert alert-error">
        {{ errorMessage }}
      </div>

      <div *ngIf="successMessage" class="alert alert-success">
        {{ successMessage }}
      </div>

      <div class="form-group">
        <label class="form-label" for="email">Email</label>
        <input
          type="email"
          id="email"
          class="form-control"
          formControlName="email"
          placeholder="Nhập email của bạn"
          [class.error]="email?.invalid && email?.touched"
        />
        <div *ngIf="email?.invalid && email?.touched" class="error-message">
          <span *ngIf="email?.errors?.['required']">Email không được để trống</span>
          <span *ngIf="email?.errors?.['email']">Email không đúng định dạng</span>
        </div>
      </div>

      <div class="form-group">
        <button
          type="submit"
          class="btn btn-primary btn-block"
          [disabled]="isLoading"
        >
          <span *ngIf="!isLoading">Gửi Mã OTP</span>
          <span *ngIf="isLoading">
            <span class="loading"></span> Đang gửi...
          </span>
        </button>
      </div>

      <div class="form-footer">
        <a (click)="backToLogin()" class="back-link">← Quay lại đăng nhập</a>
      </div>
    </form>

    <!-- Step 2: OTP -->
    <form *ngIf="step === 'otp'" [formGroup]="otpForm" (ngSubmit)="onSubmitOtp()">
      <div *ngIf="errorMessage" class="alert alert-error">
        {{ errorMessage }}
      </div>

      <div *ngIf="successMessage" class="alert alert-success">
        {{ successMessage }}
      </div>

      <div class="form-group">
        <label class="form-label" for="otp">Mã OTP (6 chữ số)</label>
        <input
          type="text"
          id="otp"
          class="form-control otp-input"
          formControlName="otp"
          placeholder="Nhập mã OTP"
          maxlength="6"
          pattern="[0-9]*"
          inputmode="numeric"
          (input)="onOtpInput($event)"
          [class.error]="otp?.invalid && otp?.touched"
        />
        <div *ngIf="otp?.invalid && otp?.touched" class="error-message">
          <span *ngIf="otp?.errors?.['required']">Mã OTP không được để trống</span>
          <span *ngIf="otp?.errors?.['pattern']">Mã OTP phải có đúng 6 chữ số</span>
        </div>
      </div>

      <div class="form-group">
        <button
          type="submit"
          class="btn btn-primary btn-block"
          [disabled]="isLoading"
        >
          <span *ngIf="!isLoading">Xác Thực OTP</span>
          <span *ngIf="isLoading">
            <span class="loading"></span> Đang xác thực...
          </span>
        </button>
      </div>

      <div class="form-footer">
        <a (click)="resendOtp()" class="resend-link">Gửi lại mã OTP</a>
        <a (click)="backToLogin()" class="back-link">← Quay lại đăng nhập</a>
      </div>
    </form>

    <!-- Step 3: New Password -->
    <form *ngIf="step === 'newPassword'" [formGroup]="newPasswordForm" (ngSubmit)="onSubmitNewPassword()">
      <div *ngIf="errorMessage" class="alert alert-error">
        {{ errorMessage }}
      </div>

      <div *ngIf="successMessage" class="alert alert-success">
        {{ successMessage }}
      </div>

      <div class="form-group">
        <label class="form-label" for="newPassword">Mật khẩu mới</label>
        <input
          type="password"
          id="newPassword"
          class="form-control"
          formControlName="newPassword"
          placeholder="Nhập mật khẩu mới (tối thiểu 6 ký tự)"
          [class.error]="newPassword?.invalid && newPassword?.touched"
        />
        <div *ngIf="newPassword?.invalid && newPassword?.touched" class="error-message">
          <span *ngIf="newPassword?.errors?.['required']">Mật khẩu không được để trống</span>
          <span *ngIf="newPassword?.errors?.['minlength']">Mật khẩu phải có ít nhất 6 ký tự</span>
        </div>
      </div>

      <div class="form-group">
        <label class="form-label" for="confirmPassword">Xác nhận mật khẩu</label>
        <input
          type="password"
          id="confirmPassword"
          class="form-control"
          formControlName="confirmPassword"
          placeholder="Nhập lại mật khẩu mới"
          [class.error]="(confirmPassword?.invalid || newPasswordForm.errors?.['passwordMismatch']) && confirmPassword?.touched"
        />
        <div *ngIf="confirmPassword?.touched && (confirmPassword?.invalid || newPasswordForm.errors?.['passwordMismatch'])" class="error-message">
          <span *ngIf="confirmPassword?.errors?.['required']">Xác nhận mật khẩu không được để trống</span>
          <span *ngIf="newPasswordForm.errors?.['passwordMismatch'] || (confirmPassword?.errors?.['passwordMismatch'])">Mật khẩu không khớp</span>
        </div>
      </div>

      <div class="form-group">
        <button
          type="submit"
          class="btn btn-primary btn-block"
          [disabled]="isLoading"
        >
          <span *ngIf="!isLoading">Đặt Mật Khẩu Mới</span>
          <span *ngIf="isLoading">
            <span class="loading"></span> Đang xử lý...
          </span>
        </button>
      </div>

      <div class="form-footer">
        <a (click)="backToLogin()" class="back-link">← Quay lại đăng nhập</a>
      </div>
    </form>
  </div>
</div>
